use kni_metrics::training_only_fit::*;
use kni_metrics::gen::{GlyphKnowledge,GlyphWall};
use std::collections::{BTreeMap,BTreeSet};
fn pin(c:char)->String{std::iter::repeat_n(c,64).collect()}
fn assignment(g:&str,query:bool)->GeometryAssignment{GeometryAssignment{glyph:g.into(),knowledge:GlyphKnowledge{case:'x',freq_weight:0,right_class:1,left_class:1},wall:GlyphWall{advance:100.,rows:BTreeMap::from([(0,(0.,80.)),(100,(0.,80.))])},outline_pin:pin('a'),prototype_pin:pin('b'),query_only:query}}
fn row(c:char,l:&str,r:&str)->Observation{Observation{row_pin:pin(c),left:l.into(),right:r.into(),kern:-20}}
fn inventory()->Vec<Observation>{vec![row('1',"a","b"),row('2',"b","a"),row('3',"q","a"),row('4',"a","q"),row('5',"qa","b"),row('6',"b","qa")]}
fn fit_part(part:&BTreeSet<String>,original:&[Observation])->FitArtifacts{let rows=original.iter().filter(|r|!part.contains(&r.left)&&!part.contains(&r.right)).cloned().collect::<Vec<_>>();fit(&rows,&[assignment("a",false),assignment("b",false)],part,&pin('b')).unwrap()}
#[test]fn different_parts_one_endpoint_held_out_both_directions(){let part=BTreeSet::from(["q".into(),"qa".into()]);let original=inventory();let f=fit_part(&part,&original);let p=predict_query_held_out_part(&f,&assignment("q",true),&assignment("a",true),&part,&original).unwrap();assert_eq!(p.prediction.predicted,Some(-20));assert_eq!(p.receipt.part_glyph_count,2);assert_eq!(p.receipt.excluded_row_count,4);assert_eq!(p.receipt.retained_row_count,2);let reverse=predict_query_held_out_part(&f,&assignment("a",true),&assignment("q",true),&part,&original).unwrap();assert_eq!(reverse.prediction.predicted,Some(-20));}
#[test]fn same_part_and_legacy_query_byte_fields_equal(){let part=BTreeSet::from(["q".into(),"qa".into()]);let original=inventory();let f=fit_part(&part,&original);let l=assignment("q",true);let r=assignment("qa",true);let old=predict_query(&f,&l,&r);let new=predict_query_held_out_part(&f,&l,&r,&part,&original).unwrap().prediction;assert_eq!(format!("{old:?}"),format!("{new:?}"));assert_eq!(f.artifact_sha256(),fit_part(&part,&original).artifact_sha256());}
#[test]fn all_exact_aliases_bound_to_part(){let original=inventory();let part=BTreeSet::from(["q".into(),"qa".into()]);let f=fit_part(&part,&original);assert!(!f.inputs.knowledge.contains_key("q"));assert!(!f.inputs.knowledge.contains_key("qa"));assert!(predict_query_held_out_part(&f,&assignment("qa",true),&assignment("b",true),&part,&original).is_ok());}
#[test]fn independent_count_proves_no_incident_training_rows(){let original=inventory();let part=BTreeSet::from(["q".into(),"qa".into()]);let f=fit_part(&part,&original);let count=original.iter().filter(|r|f.training_row_pins.contains(&r.row_pin)&&(part.contains(&r.left)||part.contains(&r.right))).count();assert_eq!(count,0);let mut corrupted=f.clone();corrupted.training_row_pins.push(pin('3'));assert!(matches!(predict_query_held_out_part(&corrupted,&assignment("q",true),&assignment("a",true),&part,&original),Err(HeldOutPartError::PartGlyphInTraining(_))));}
#[test]fn typed_empty_outside_and_inventory_errors(){let original=inventory();let part=BTreeSet::from(["q".into(),"qa".into()]);let f=fit_part(&part,&original);assert!(matches!(predict_query_held_out_part(&f,&assignment("q",true),&assignment("a",true),&BTreeSet::new(),&original),Err(HeldOutPartError::EmptyPart)));assert!(matches!(predict_query_held_out_part(&f,&assignment("a",true),&assignment("b",true),&part,&original),Err(HeldOutPartError::QueryOutsidePart)));assert!(matches!(predict_query_held_out_part(&f,&assignment("q",true),&assignment("a",true),&part,&original[1..]),Err(HeldOutPartError::TrainingInventoryMismatch)));}
#[test]fn trained_partner_mismatch_and_unbound_part_are_typed(){let original=inventory();let part=BTreeSet::from(["q".into(),"qa".into()]);let f=fit_part(&part,&original);let mut partner=assignment("a",true);partner.wall.advance=101.;assert!(matches!(predict_query_held_out_part(&f,&assignment("q",true),&partner,&part,&original),Err(HeldOutPartError::PartnerMismatch(_))));let other=BTreeSet::from(["q".into(),"qa".into(),"missing".into()]);assert!(matches!(predict_query_held_out_part(&f,&assignment("q",true),&assignment("a",true),&other,&original),Err(HeldOutPartError::PartNotBoundToFit(_))));let old=predict_query(&f,&assignment("q",true),&assignment("a",true));assert_eq!(old.unavailable_reason.as_deref(),Some("query not bound to excluded target glyph"));}
#[test]fn varied_kern_partner_consistency_and_batch(){let mut original=inventory();original[0].kern=-10;original[1].kern=-30;let part=BTreeSet::from(["q".into(),"qa".into()]);let f=fit_part(&part,&original);let l=assignment("q",true);let r=assignment("a",true);let out=predict_query_held_out_part(&f,&l,&r,&part,&original).unwrap();assert_eq!(out.prediction.predicted,Some(-20));let mut reference=f.clone();reference.excluded_glyphs.push("a".into());let expected=predict_query(&reference,&l,&r);assert_eq!(format!("{:?}",out.prediction),format!("{expected:?}"));let before=f.artifact_sha256();let batch=predict_query_held_out_part_batch(&f,&[(l.clone(),r.clone()),(r,l)],&part,&original).unwrap();assert_eq!(batch.len(),2);assert_eq!(batch[0].prediction.predicted,Some(-20));assert_eq!(f.artifact_sha256(),before);}
#[test]fn sorted_pin_inventory_binding_mixed_insertion_order(){let original=vec![row('1',"z","a"),row('2',"a","z"),row('3',"q","z")];let part=BTreeSet::from(["q".into()]);let mut z=assignment("z",false);z.outline_pin=pin('c');let mut a=assignment("a",false);a.outline_pin=pin('d');let retained=original[..2].to_vec();let f=fit(&retained,&[z.clone(),a],&part,&pin('b')).unwrap();assert_eq!(f.training_outline_pins,vec![pin('d'),pin('c')]);z.query_only=true;assert!(predict_query_held_out_part(&f,&assignment("q",true),&z,&part,&original).is_ok());let mut corrupt=f;corrupt.training_outline_pins.reverse();assert!(matches!(predict_query_held_out_part(&corrupt,&assignment("q",true),&z,&part,&original),Err(HeldOutPartError::PartnerMismatch(_))));}
#[test]fn batch_outside_part_error_reports_index(){let original=inventory();let part=BTreeSet::from(["q".into(),"qa".into()]);let f=fit_part(&part,&original);let pairs=vec![(assignment("q",true),assignment("a",true)),(assignment("a",true),assignment("b",true))];assert!(matches!(predict_query_held_out_part_batch(&f,&pairs,&part,&original),Err(HeldOutPartError::QueryOutsidePartAt(1))));}
#[test]fn outline_inventory_cardinality_guard_is_typed(){let original=inventory();let part=BTreeSet::from(["q".into(),"qa".into()]);let mut f=fit_part(&part,&original);f.training_outline_pins.pop();assert!(matches!(predict_query_held_out_part(&f,&assignment("q",true),&assignment("a",true),&part,&original),Err(HeldOutPartError::TrainingOutlineInventoryMismatch)));}
